  "DrawTextWindowAndBufferTiles": {
    returnType: "void",
    params: "const u8 *string, void *dst, u8 zero1, u8 zero2, s32 bytesToBuffer",
    callsTo: ["AddTextPrinterParameterized4","AddWindow","CpuCopy16","CpuFill16","FillWindowPixelBuffer","GetWindowAttribute","PIXEL_FILL","RemoveWindow"],
    lineCount: 36,
    bodyC: "s32 i, tileBytesToBuffer, remainingBytes;\n    u16 windowId;\n    u8 txtColor[3];\n    u8 *tileData1, *tileData2;\n    struct WindowTemplate winTemplate = {0};\n\n    winTemplate.width = 24;\n    winTemplate.height = 2;\n    windowId = AddWindow(&winTemplate);\n    FillWindowPixelBuffer(windowId, PIXEL_FILL(zero2));\n    tileData1 = (u8 *) GetWindowAttribute(windowId, WINDOW_TILE_DATA);\n    tileData2 = (winTemplate.width * TILE_SIZE_4BPP) + tileData1;\n\n    if (!zero1)\n        txtColor[0] = TEXT_COLOR_TRANSPARENT;\n    else\n        txtColor[0] = zero2;\n    txtColor[1] = TEXT_DYNAMIC_COLOR_6;\n    txtColor[2] = TEXT_DYNAMIC_COLOR_5;\n    AddTextPrinterParameterized4(windowId, FONT_NORMAL, 0, 1, 0, 0, txtColor, TEXT_SKIP_DRAW, string);\n\n    tileBytesToBuffer = bytesToBuffer;\n    if (tileBytesToBuffer > 6u)\n        tileBytesToBuffer = 6;\n    remainingBytes = bytesToBuffer - 6;\n    if (tileBytesToBuffer > 0)\n    {\n        for (i = tileBytesToBuffer; i != 0; i--)\n        {\n            CpuCopy16(tileData1, dst, 0x80);\n            CpuCopy16(tileData2, dst + 0x80, 0x80);\n            tileData1 += 0x80;\n            tileData2 += 0x80;\n            dst += 0x100;\n        }\n    }\n\n     \n    if (remainingBytes > 0)\n        CpuFill16((zero2 << 4) | zero2, dst, (u32)(remainingBytes) * 0x100);\n\n    RemoveWindow(windowId);",
  },
  "DrawWallpaper": {
    returnType: "static void",
    params: "const void *tilemap, s8 direction, u8 offset",
    callsTo: ["CopyRectToBgTilemapBufferRect","FillBgTilemapBufferRect"],
    lineCount: 11,
    bodyC: "s16 tileOffset = offset * 256;\n    s16 paletteNum = (offset * 2) + 3;\n    s16 x = ((sStorage->bg2_X / 8 + 10) + (direction * 24)) & 0x3F;\n\n    CopyRectToBgTilemapBufferRect(2, tilemap, 0, 0, 20, 18, x, 2, 20, 18, 17, tileOffset, paletteNum);\n\n    if (direction == 0)\n        return;\n    if (direction > 0)\n        x += 20;\n    else\n        x -= 4;\n\n    FillBgTilemapBufferRect(2, 0, x, 2, 4, 0x12, 17);",
  },
