    bodyC: "u16 species = GetSpeciesAtCursorPosition();\n\n    switch (sStorage->boxOption)\n    {\n    case OPTION_DEPOSIT:\n        if (species != SPECIES_NONE)\n            SetMenuText(MENU_STORE);\n        else\n            return FALSE;\n        break;\n    case OPTION_WITHDRAW:\n        if (species != SPECIES_NONE)\n            SetMenuText(MENU_WITHDRAW);\n        else\n            return FALSE;\n        break;\n    case OPTION_MOVE_MONS:\n        if (sIsMonBeingMoved)\n        {\n            if (species != SPECIES_NONE)\n                SetMenuText(MENU_SHIFT);\n            else\n                SetMenuText(MENU_PLACE);\n        }\n        else\n        {\n            if (species != SPECIES_NONE)\n                SetMenuText(MENU_MOVE);\n            else\n                return FALSE;\n        }\n        break;\n    case OPTION_MOVE_ITEMS:\n    default:\n        return FALSE;\n    }\n\n    SetMenuText(MENU_SUMMARY);\n    if (sStorage->boxOption == OPTION_MOVE_MONS)\n    {\n        if (sCursorArea == CURSOR_AREA_IN_BOX)\n            SetMenuText(MENU_WITHDRAW);\n        else\n            SetMenuText(MENU_STORE);\n    }\n\n    SetMenuText(MENU_MARK);\n    SetMenuText(MENU_RELEASE);\n    SetMenuText(MENU_CANCEL);\n    return TRUE;",
