    bodyC: "switch (sStorage->state)\n    {\n    case 0:\n        PrintMessage(MSG_RELEASE_POKE);\n        ShowYesNoWindow(1);\n        sStorage->state++;\n         \n    case 1:\n        switch (Menu_ProcessInputNoWrapClearOnChoose())\n        {\n        case MENU_B_PRESSED:\n        case  1:  \n            ClearBottomWindow();\n            SetPokeStorageTask(Task_PokeStorageMain);\n            break;\n        case  0:  \n            ClearBottomWindow();\n            InitCanReleaseMonVars();\n            InitReleaseMon();\n            sStorage->state++;\n            break;\n        }\n        break;\n    case 2:\n        RunCanReleaseMon();\n        if (!TryHideReleaseMon())\n        {\n            while (1)\n            {\n                s8 canRelease = RunCanReleaseMon();\n                if (canRelease == TRUE)\n                {\n                    sStorage->state++;\n                    break;\n                }\n                else if (!canRelease)\n                {\n                    sStorage->state = 8;\n                    break;\n                }\n            }\n        }\n        break;\n    case 3:\n        ReleaseMon();\n        RefreshDisplayMonData();\n        PrintMessage(MSG_WAS_RELEASED);\n        sStorage->state++;\n        break;\n    case 4:\n        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))\n        {\n            PrintMessage(MSG_BYE_BYE);\n            sStorage->state++;\n        }\n        break;\n    case 5:\n        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))\n        {\n            ClearBottomWindow();\n            if (sInPartyMenu)\n            {\n                CompactPartySlots();\n                CompactPartySprites();\n                sStorage->state++;\n            }\n            else\n            {\n                sStorage->state = 7;\n            }\n        }\n        break;\n    case 6:\n        if (GetNumPartySpritesCompacting() == 0)\n        {\n            RefreshDisplayMon();\n            StartDisplayMonMosaicEffect();\n            UpdatePartySlotColors();\n            sStorage->state++;\n        }\n        break;\n    case 7:\n        SetPokeStorageTask(Task_PokeStorageMain);\n        break;\n    case 8:\n         \n        PrintMessage(MSG_WAS_RELEASED);\n        sStorage->state++;\n        break;\n    case 9:\n        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))\n        {\n            PrintMessage(MSG_SURPRISE);\n            sStorage->state++;\n        }\n        break;\n    case 10:\n        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))\n        {\n            ClearBottomWindow();\n            ReshowReleaseMon();\n            sStorage->state++;\n        }\n        break;\n    case 11:\n        if (!ResetReleaseMonSpritePtr())\n        {\n            TrySetCursorFistAnim();\n            PrintMessage(MSG_CAME_BACK);\n            sStorage->state++;\n        }\n        break;\n    case 12:\n        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))\n        {\n            PrintMessage(MSG_WORRIED);\n            sStorage->state++;\n        }\n        break;\n    case 13:\n        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))\n        {\n            ClearBottomWindow();\n            SetPokeStorageTask(Task_PokeStorageMain);\n        }\n        break;\n    }",
